def _seed_system_roles() -> None:
    # System roles and default permissions from DOA.md (configuration, not demo data).
    roles = sa.table(
        "roles",
        sa.column("id", sa.UUID()),
        sa.column("code", sa.String()),
        sa.column("name", sa.String()),
        sa.column("is_system", sa.Boolean()),
        sa.column("is_external", sa.Boolean()),
        sa.column("requires_2fa", sa.Boolean()),
    )
    perms = sa.table(
        "role_permissions",
        sa.column("role_id", sa.UUID()),
        sa.column("module", sa.String()),
        sa.column("action", sa.String()),
        sa.column("scope", sa.String()),
    )
    role_rows, perm_rows = [], []
    for r in SYSTEM_ROLES:
        rid = uuid.uuid4()
        role_rows.append(
            {
                "id": rid,
                "code": r.code,
                "name": r.name,
                "is_system": True,
                "is_external": r.is_external,
                "requires_2fa": r.requires_2fa,
            }
        )
        perm_rows += [{"role_id": rid, "module": m, "action": a, "scope": sc} for m, a, sc in r.grants]
    op.bulk_insert(roles, role_rows)
    op.bulk_insert(perms, perm_rows)


